__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"RUQYAH",{enumerable:!0,get:function(){return n}});const n=[{key:'ayatulKursi',reference:'B\u0259q\u0259r\u0259, 255',arabic:'\u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u064e\u0651\u0627 \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064f\u0651 \u0627\u0644\u0652\u0642\u064e\u064a\u064f\u0651\u0648\u0645\u064f \u06da \u0644\u064e\u0627 \u062a\u064e\u0623\u0652\u062e\u064f\u0630\u064f\u0647\u064f \u0633\u0650\u0646\u064e\u0629\u064c \u0648\u064e\u0644\u064e\u0627 \u0646\u064e\u0648\u0652\u0645\u064c \u06da \u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0645\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d7 \u0645\u064e\u0646\u0652 \u0630\u064e\u0627 \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u064a\u064e\u0634\u0652\u0641\u064e\u0639\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u0651\u0627 \u0628\u0650\u0625\u0650\u0630\u0652\u0646\u0650\u0647\u0650 \u06da \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u062e\u064e\u0644\u0652\u0641\u064e\u0647\u064f\u0645\u0652 \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u064a\u0637\u064f\u0648\u0646\u064e \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0645\u0650\u0646\u0652 \u0639\u0650\u0644\u0652\u0645\u0650\u0647\u0650 \u0625\u0650\u0644\u064e\u0651\u0627 \u0628\u0650\u0645\u064e\u0627 \u0634\u064e\u0627\u0621\u064e \u06da \u0648\u064e\u0633\u0650\u0639\u064e \u0643\u064f\u0631\u0652\u0633\u0650\u064a\u064f\u0651\u0647\u064f \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0626\u064f\u0648\u062f\u064f\u0647\u064f \u062d\u0650\u0641\u0652\u0638\u064f\u0647\u064f\u0645\u064e\u0627 \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0652\u0639\u064e\u0644\u0650\u064a\u064f\u0651 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u064f',meaning:'Allah \u2014 Ondan ba\u015fqa ilah yoxdur. O, \u0259b\u0259di Diri v\u0259 h\u0259r \u015feyi idar\u0259 ed\u0259ndir. Onu n\u0259 m\xfcrg\xfc, n\u0259 d\u0259 yuxu tutar. G\xf6yl\u0259rd\u0259 v\u0259 yerd\u0259 n\u0259 varsa Onundur. Onun izni olmadan Onun yan\u0131nda kim \u015f\u0259fa\u0259t ed\u0259 bil\u0259r? O, m\u0259xluqat\u0131n \xf6n\xfcnd\u0259kini v\u0259 arxas\u0131ndak\u0131n\u0131 bilir. Onlar Onun elmind\u0259n, \xd6z\xfcn\xfcn ist\u0259diyind\u0259n ba\u015fqa he\xe7 bir \u015feyi \u0259hat\u0259 ed\u0259 bilm\u0259zl\u0259r. Onun K\xfcrs\xfcs\xfc g\xf6yl\u0259ri v\u0259 yeri \u0259hat\u0259 etmi\u015fdir. Bunlar\u0131 qorumaq Ona a\u011f\u0131r g\u0259lm\u0259z. O, Ucad\u0131r, B\xf6y\xfckd\xfcr.'},{key:'ikhlas',reference:'\u0130xlas, 112',arabic:'\u0642\u064f\u0644\u0652 \u0647\u064f\u0648\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c \u06dd \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0627\u0644\u0635\u064e\u0651\u0645\u064e\u062f\u064f \u06dd \u0644\u064e\u0645\u0652 \u064a\u064e\u0644\u0650\u062f\u0652 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0648\u0644\u064e\u062f\u0652 \u06dd \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u064e\u0647\u064f \u0643\u064f\u0641\u064f\u0648\u064b\u0627 \u0623\u064e\u062d\u064e\u062f\u064c',translit:'Qul huv\u0259llahu \u0259h\u0259d. Allahus-sam\u0259d. L\u0259m y\u0259lid v\u0259 l\u0259m yul\u0259d. V\u0259 l\u0259m y\u0259kun l\u0259hu kufuv\u0259n \u0259h\u0259d.',meaning:'De: "O, Allah birdir. Allah Sam\u0259ddir (he\xe7 n\u0259y\u0259 m\xf6htac deyil, h\u0259r \u015fey Ona m\xf6htacd\u0131r). O, n\u0259 do\u011fub, n\u0259 do\u011fulub. Onun he\xe7 bir tay\u0131-b\u0259rab\u0259ri yoxdur."'},{key:'falaq',reference:'F\u0259l\u0259q, 113',arabic:'\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0652\u0641\u064e\u0644\u064e\u0642\u0650 \u06dd \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0645\u064e\u0627 \u062e\u064e\u0644\u064e\u0642\u064e \u06dd \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u063a\u064e\u0627\u0633\u0650\u0642\u064d \u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e \u06dd \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0627\u0644\u0646\u064e\u0651\u0641\u064e\u0651\u0627\u062b\u064e\u0627\u062a\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0639\u064f\u0642\u064e\u062f\u0650 \u06dd \u0648\u064e\u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u062d\u064e\u0627\u0633\u0650\u062f\u064d \u0625\u0650\u0630\u064e\u0627 \u062d\u064e\u0633\u064e\u062f\u064e',translit:'Qul \u0259uzu birabbil-f\u0259l\u0259q. Min \u015f\u0259rri m\u0259 x\u0259l\u0259q. V\u0259 min \u015f\u0259rri \u011fasiqin iz\u0259 v\u0259qab. V\u0259 min \u015f\u0259rrin-n\u0259ff\u0259s\u0259ti fil-uqad. V\u0259 min \u015f\u0259rri h\u0259sidin iz\u0259 h\u0259s\u0259d.',meaning:'De: "S\u0131\u011f\u0131n\u0131ram s\xfcbh\xfcn R\u0259bbin\u0259, yaratd\u0131qlar\u0131n\u0131n \u015f\u0259rind\u0259n, qaranl\u0131\u011f\u0131 \xe7\xf6k\u0259n gec\u0259nin \u015f\u0259rind\u0259n, d\xfcy\xfcnl\u0259r\u0259 \xfcf\xfcr\u0259n (cadug\u0259r) qad\u0131nlar\u0131n \u015f\u0259rind\u0259n v\u0259 h\u0259s\u0259d apard\u0131qda pax\u0131l\u0131n \u015f\u0259rind\u0259n."'},{key:'nas',reference:'Nas, 114',arabic:'\u0642\u064f\u0644\u0652 \u0623\u064e\u0639\u064f\u0648\u0630\u064f \u0628\u0650\u0631\u064e\u0628\u0650\u0651 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u06dd \u0645\u064e\u0644\u0650\u0643\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u06dd \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u06dd \u0645\u0650\u0646\u0652 \u0634\u064e\u0631\u0650\u0651 \u0627\u0644\u0652\u0648\u064e\u0633\u0652\u0648\u064e\u0627\u0633\u0650 \u0627\u0644\u0652\u062e\u064e\u0646\u064e\u0651\u0627\u0633\u0650 \u06dd \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u064a\u064f\u0648\u064e\u0633\u0652\u0648\u0650\u0633\u064f \u0641\u0650\u064a \u0635\u064f\u062f\u064f\u0648\u0631\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u06dd \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062c\u0650\u0646\u064e\u0651\u0629\u0650 \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650',translit:'Qul \u0259uzu birabbin-n\u0259s. M\u0259likin-n\u0259s. \u0130l\u0259hin-n\u0259s. Min \u015f\u0259rril-v\u0259sv\u0259sil-x\u0259nn\u0259s. \u018fll\u0259zi yuv\u0259svisu fi sudurin-n\u0259s. Min\u0259l-cinn\u0259ti v\u0259n-n\u0259s.',meaning:'De: "S\u0131\u011f\u0131n\u0131ram insanlar\u0131n R\u0259bbin\u0259, insanlar\u0131n H\xf6kmdar\u0131na, insanlar\u0131n \u0130lah\u0131na \u2014 sin\u0259l\u0259r\u0259 v\u0259sv\u0259s\u0259 salan, (Allah an\u0131ld\u0131qda) geri \xe7\u0259kil\u0259n v\u0259sv\u0259s\u0259\xe7inin \u015f\u0259rind\u0259n; o ki, cinl\u0259rd\u0259n v\u0259 insanlardan olur."'},{key:'baqarahEnd',reference:'B\u0259q\u0259r\u0259, 285\u2013286 (son ay\u0259l\u0259r)',arabic:'\u0622\u0645\u064e\u0646\u064e \u0627\u0644\u0631\u064e\u0651\u0633\u064f\u0648\u0644\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u0650\u0646\u0652 \u0631\u064e\u0628\u0650\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e \u06da \u0643\u064f\u0644\u064c\u0651 \u0622\u0645\u064e\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06da \u0644\u064e\u0627 \u0646\u064f\u0641\u064e\u0631\u0650\u0651\u0642\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0623\u064e\u062d\u064e\u062f\u064d \u0645\u0650\u0646\u0652 \u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u06da \u0631\u064e\u0628\u064e\u0651\u0646\u064e\u0627 \u0644\u064e\u0627 \u062a\u064f\u0624\u064e\u0627\u062e\u0650\u0630\u0652\u0646\u064e\u0627 \u0625\u0650\u0646\u0652 \u0646\u064e\u0633\u0650\u064a\u0646\u064e\u0627 \u0623\u064e\u0648\u0652 \u0623\u064e\u062e\u0652\u0637\u064e\u0623\u0652\u0646\u064e\u0627',meaning:'Pey\u011f\u0259mb\u0259r d\u0259, m\xf6minl\u0259r d\u0259 R\u0259bbind\u0259n ona nazil edil\u0259n\u0259 iman g\u0259tirdi. Ham\u0131s\u0131 Allaha, m\u0259l\u0259kl\u0259rin\u0259, kitablar\u0131na v\u0259 pey\u011f\u0259mb\u0259rl\u0259rin\u0259 inand\u0131. "Onun pey\u011f\u0259mb\u0259rl\u0259ri aras\u0131nda f\u0259rq qoymuruq" (dedil\u0259r). "Ey R\u0259bbimiz! Unutsaq v\u0259 ya x\u0259ta ets\u0259k bizi c\u0259zaland\u0131rma..."'}]},1987,[]);
